std::vector<Node> path;
std::vector<Node*> open_list;
std::unordered_map<int, bool> closed_list;

// Initialize start node
Node& start_node = graph.SNodes()[start_idx];
Node& end_node = graph.SNodes()[end_idx];
start_node.g_value = 0.0f;
start_node.h_value = start_node.distance(end_node);
start_node.visited = false;
open_list.push_back(&start_node);

while (!open_list.empty()) {
    // Find node with lowest f_value = g_value + h_value
    Node* current = open_list[0];
    int current_index = 0;
    for (int i = 1; i < open_list.size(); i++) {
        float f_current = open_list[i]->g_value + open_list[i]->h_value;
        float f_best = current->g_value + current->h_value;
        if (f_current < f_best) {
            current = open_list[i];
            current_index = i;
        }
    }

    // Remove current from open_list
    open_list.erase(open_list.begin() + current_index);

    // Check if we reached the goal
    if (current == &end_node) {
        // Construct path by backtracking from end to start
        Node* temp = current;
        while (temp != nullptr) {
            path.push_back(*temp);
            temp = temp->parent;
        }
        std::reverse(path.begin(), path.end());
        return path;
    }

    // Mark current as visited
    closed_list[current->index_] = true;

    // Find neighbors
    current->find_neighbors();
    for (Node* neighbor : current->neighbors) {
        // Skip if already visited
        if (closed_list.find(neighbor->index_) != closed_list.end()) {
            continue;
        }

        float tentative_g = current->g_value + current->distance(*neighbor);

        // Check if this path to neighbor is better
        bool better_path = false;
        if (neighbor->visited == false) {
            neighbor->visited = true;
            better_path = true;
        } else if (tentative_g < neighbor->g_value) {
            better_path = true;
        }

        if (better_path) {
            neighbor->parent = current;
            neighbor->g_value = tentative_g;
            neighbor->h_value = neighbor->distance(end_node);

            // Add to open_list if not already there
            bool in_open_list = false;
            for (Node* open_node : open_list) {
                if (open_node == neighbor) {
                    in_open_list = true;
                    break;
                }
            }
            if (!in_open_list) {
                open_list.push_back(neighbor);
            }
        }
    }
}

// No path found
return path;

